WITH flattened_attrs AS (SELECT id, service, host, level, latency_ms, ARRAY_CONTAINS(MAP_KEYS(context), 'trace') AS has_trace, SHIFTRIGHT(status_code, 2) AS status_code_high, COALESCE(context['version'], 'direct') AS version_or_default, COALESCE(context['region'], 'none') AS region_or_default FROM app_logs) SELECT CASE WHEN latency_ms >= 2434 THEN 'PREMIUM' ELSE 'STANDARD' END AS latency_ms_tier, SUM(status_code_high) AS total_status_code_high, COUNT(*) AS cnt, SUM(status_code_high) FILTER (WHERE level = 'INFO') AS info_total_status_code_high, COUNT_IF(level = 'ERROR') AS error_events, COUNT(DISTINCT id) AS distinct_ids FROM flattened_attrs GROUP BY 1;
